/// <summary>
/// PaffH 10.05.24
/// set QR-Code images
/// </summary>
public void setQRCodeImage()
{
    Counter c1 = 0;
    List listNDXProdIdentControlPanel = sysWizard.parmNDXProdIdentControlPanelList();
    ListEnumerator enum = listNDXProdIdentControlPanel.getEnumerator();
    while (enum.moveNext())
    {
        ++c1;
        NDXProdIdentControlPanel nDXProdIdentControlPanel = enum.current();

        switch (c1)
        {
            case 1:
                NDXProdIdentControlPanelTmp.ProdLabelId = nDXProdIdentControlPanel.ProdLabelId;
                NDXProdIdentControlPanelTmp.LabelId = nDXProdIdentControlPanel.LabelId;
                NDXHelperQRCode::setQRCodeImage(NDXProdIdentControlPanelTmp.ProdLabelId, FormImageQRCodeProdLabelId);
                NDXHelperQRCode::setQRCodeImage(NDXProdIdentControlPanelTmp.LabelId, FormImageQRCodeLabelId);
                FormGroupQRCodeProdLabelIdArrange.Visible(true);
                FormGroupQRCodeLabelIdArrange.Visible(true);
                FormGroupQRCodeAdditionalData1.visible(true);
                NDXProdIdentControlPanelTmp.TechniqueId = nDXProdIdentControlPanel.TechniqueId;
                NDXProdIdentControlPanelTmp.AnzahlEtiketten = nDXProdIdentControlPanel.AnzahlEtiketten;
                break;
            case 2:
                NDXProdIdentControlPanelTmp2.ProdLabelId = nDXProdIdentControlPanel.ProdLabelId;
                NDXProdIdentControlPanelTmp2.LabelId = nDXProdIdentControlPanel.LabelId;
                NDXHelperQRCode::setQRCodeImage(NDXProdIdentControlPanelTmp2.ProdLabelId, FormImageQRCodeProdLabelId2);
                NDXHelperQRCode::setQRCodeImage(NDXProdIdentControlPanelTmp2.LabelId, FormImageQRCodeLabelId2);
                FormGroupQRCodeProdLabelIdArrange2.Visible(true);
                FormGroupQRCodeLabelIdArrange2.Visible(true);
                FormGroupQRCodeAdditionalData2.visible(true);
                NDXProdIdentControlPanelTmp2.AnzahlEtiketten = nDXProdIdentControlPanel.AnzahlEtiketten;
                NDXProdIdentControlPanelTmp2.RouteId = nDXProdIdentControlPanel.RouteId;
                NDXProdIdentControlPanelTmp2.TechniqueId = nDXProdIdentControlPanel.TechniqueId;
                NDXProdIdentControlPanelTmp2.insert();
                NDXProdIdentControlPanelTmp2_DS.refresh();
                break;
            default:
                NDXProdIdentControlPanelTmp3.ProdLabelId = nDXProdIdentControlPanel.ProdLabelId;
                NDXProdIdentControlPanelTmp3.LabelId = nDXProdIdentControlPanel.LabelId;
                NDXHelperQRCode::setQRCodeImage(NDXProdIdentControlPanelTmp3.ProdLabelId, FormImageQRCodeProdLabelId3);
                NDXHelperQRCode::setQRCodeImage(NDXProdIdentControlPanelTmp3.LabelId, FormImageQRCodeLabelId3);
                FormGroupQRCodeProdLabelIdArrange3.Visible(true);
                FormGroupQRCodeLabelIdArrange3.Visible(true);
                FormGroupQRCodeAdditionalData3.visible(true);
                NDXProdIdentControlPanelTmp3.AnzahlEtiketten = nDXProdIdentControlPanel.AnzahlEtiketten;
                NDXProdIdentControlPanelTmp3.RouteId = nDXProdIdentControlPanel.RouteId;
                NDXProdIdentControlPanelTmp3.TechniqueId = nDXProdIdentControlPanel.TechniqueId;
                NDXProdIdentControlPanelTmp3.insert();
                NDXProdIdentControlPanelTmp3_DS.refresh();
        }                
    }
    if (c1 > 0)
    {
        NDXSSRSReportProdTableProdIdent.Visible(true);
    }
}

/// <summary>
/// PaffH 07.05.24
/// display selected item
/// </summary>
/// <param name = "_recId">InventTable.RecId</param>
public void setInventTableSelected(RecId _recId)
{
    InventTableSelected_ds.positionToRecordByValue(fieldNum(InventTable, RecId), queryValue(_recId));

    // exists an VP label for the selected item?
    NDXProdIdentControlPanelTmp.ItemId = InventTableSelected.ItemId;

    Query query = new Query(queryStr(NDXProdIdentWithVPLabelQuery));
    QueryBuildDataSource qbds = query.dataSourceTable(tableNum(InventTable));
    SysQuery::findOrCreateRange(qbds, fieldNum(InventTable, ItemId)).value(InventTableSelected.ItemId);
    QueryRun qr = new QueryRun(query);
    if (qr.next())
    {
        sysWizard.nextEnabled(true);
        FormGroupItemInvalid.visible(false);
    }
    else
    {
        FormGroupItemInvalid.visible(true);
    }
}

/// <summary>
/// PaffH 08.05.24
/// </summary>
public void fillNDXProdIdentControlPanel()
{
    NDXProdIdentControlPanel nDXProdIdentControlPanel;
    RefRecId nDXProdIdentControlPanelParentRecId;
    NDXProdIdentProcedureLine2 nDXProdIdentProcedureLine2Loc;
    NDXProdIdentProcedureLine1 nDXProdIdentProcedureLine1Loc;
    NDXProdIdentProcedureTable nDXProdIdentProcedureTableLoc;
    NDXProdIdentTechnique nDXProdIdentTechniqueLoc;
    NDXProdIdentLabel nDXProdIdentLabelLoc;
    UnitOfMeasureConversion unitOfMeasureConversionLoc;
    InventTable inventTableLoc;
    Route routeLoc;
    boolean lFirst;

    sysWizard.initializeNDXProdIdentControlPanelList();
    nDXProdIdentProcedureLine1Loc = NDXProdIdentProcedureLine1::findRecId(NDXProdIdentProcedureLine2Selected.NDXProdIdentProcedureLine1);
    nDXProdIdentProcedureTableLoc = NDXProdIdentProcedureTable::findNDXProdIdentProcedureLine1(nDXProdIdentProcedureLine1Loc);
    Query q = new Query();
    QueryBuildDataSource qbdsNDXProdIdentProcedureLine2 = q.addDataSource(tableNum(NDXProdIdentProcedureLine2));

    QueryBuildDataSource qbdsNDXProdIdentProcedureLine1 = qbdsNDXProdIdentProcedureLine2.addDataSource(tableNum(NDXProdIdentProcedureLine1));
    qbdsNDXProdIdentProcedureLine1.joinMode(JoinMode::InnerJoin);
    qbdsNDXProdIdentProcedureLine1.fetchMode(QueryFetchMode::One2One);
    qbdsNDXProdIdentProcedureLine1.relations(true);
    qbdsNDXProdIdentProcedureLine1.addRange(fieldNum(NDXProdIdentProcedureLine1, RecId)).value(queryValue(nDXProdIdentProcedureLine1Loc.RecId));

    QueryBuildDataSource qbdsRoute = qbdsNDXProdIdentProcedureLine1.addDataSource(tableNum(Route));
    qbdsRoute.joinMode(JoinMode::InnerJoin);
    qbdsRoute.fetchMode(QueryFetchMode::One2One);
    qbdsRoute.relations(true);

    QueryBuildDataSource qbdsUnitOfMeasureConversion = qbdsNDXProdIdentProcedureLine2.addDataSource(tableNum(UnitOfMeasureConversion));
    qbdsUnitOfMeasureConversion.joinMode(JoinMode::InnerJoin);
    qbdsUnitOfMeasureConversion.fetchMode(QueryFetchMode::One2One);
    qbdsUnitOfMeasureConversion.relations(true);

    QueryBuildDataSource qbdsNDXProdIdentLabel = qbdsNDXProdIdentProcedureLine2.addDataSource(tableNum(NDXProdIdentLabel));
    qbdsNDXProdIdentLabel.joinMode(JoinMode::InnerJoin);
    qbdsNDXProdIdentLabel.fetchMode(QueryFetchMode::One2One);
    qbdsNDXProdIdentLabel.relations(true);

    QueryBuildDataSource qbdsNDXProdIdentTechnique = qbdsNDXProdIdentProcedureLine2.addDataSource(tableNum(NDXProdIdentTechnique));
    qbdsNDXProdIdentTechnique.joinMode(JoinMode::InnerJoin);
    qbdsNDXProdIdentTechnique.fetchMode(QueryFetchMode::One2One);
    qbdsNDXProdIdentTechnique.relations(true);

    QueryBuildDataSource qbdsNDXProdIdentProcedureTable = qbdsNDXProdIdentProcedureLine1.addDataSource(tableNum(NDXProdIdentProcedureTable));
    qbdsNDXProdIdentProcedureTable.joinMode(JoinMode::InnerJoin);
    qbdsNDXProdIdentProcedureTable.fetchMode(QueryFetchMode::One2One);
    qbdsNDXProdIdentProcedureTable.relations(true);


    QueryBuildDataSource qbdsInventTable = qbdsNDXProdIdentProcedureTable.addDataSource(tableNum(InventTable));
    qbdsInventTable.joinMode(JoinMode::InnerJoin);
    qbdsInventTable.fetchMode(QueryFetchMode::One2One);
    qbdsInventTable.relations(true);

    NDXProdIdentManualId nDXProdIdentManualId = NDXProdIdentControlPanel::generateManualId();
    lFirst = true;
    QueryRun qr = new QueryRun(q);
    while (qr.next())
    {
        if (qr.changed(tableNum(NDXProdIdentProcedureLine2)))
        {
            nDXProdIdentProcedureLine2Loc = qr.get(tableNum(NDXProdIdentProcedureLine2));
        }
        if (qr.changed(tableNum(NDXProdIdentProcedureLine1)))
        {
            nDXProdIdentProcedureLine1Loc = qr.get(tableNum(NDXProdIdentProcedureLine1));
        }
        if (qr.changed(tableNum(NDXProdIdentProcedureTable)))
        {
            nDXProdIdentProcedureTableLoc = qr.get(tableNum(NDXProdIdentProcedureTable));
        }
        if (qr.changed(tableNum(NDXProdIdentTechnique)))
        {
            nDXProdIdentTechniqueLoc = qr.get(tableNum(NDXProdIdentTechnique));
        }
        if (qr.changed(tableNum(NDXProdIdentLabel)))
        {
            nDXProdIdentLabelLoc = qr.get(tableNum(NDXProdIdentLabel));
        }
        if (qr.changed(tableNum(UnitOfMeasureConversion)))
        {
            unitOfMeasureConversionLoc = qr.get(tableNum(UnitOfMeasureConversion));
        }
        if (qr.changed(tableNum(UnitOfMeasureConversion)))
        {
            unitOfMeasureConversionLoc = qr.get(tableNum(UnitOfMeasureConversion));
        }
        if (qr.changed(tableNum(InventTable)))
        {
            inventTableLoc = qr.get(tableNum(InventTable));
        }
        if (qr.changed(tableNum(Route)))
        {
            routeLoc = qr.get(tableNum(Route));
        }

        nDXProdIdentControlPanel.clear();
        buf2Buf(NDXProdIdentControlPanelTmp, nDXProdIdentControlPanel);
        nDXProdIdentControlPanel.BTAction = NDXProdIdentBTAction::insert;
        nDXProdIdentControlPanel.ProdIdentManualId = nDXProdIdentManualId;
        nDXProdIdentControlPanel.RefRecIdProdIdent_ProcedureLine2 = nDXProdIdentProcedureLine2Loc.RecId;
        nDXProdIdentControlPanel.ControlPanelDataFrom = NDXProdIdentControlPanelDataFrom::Manual;
        nDXProdIdentControlPanel.OprId = routeLoc.OprId;
        nDXProdIdentControlPanel.OprNum = routeLoc.OprNum;
        nDXProdIdentControlPanel.RouteId = routeLoc.RouteId;
        nDXProdIdentControlPanel.ItemId = inventTableLoc.ItemId;
        nDXProdIdentControlPanel.Uebertragung_aus_AX = DateTimeUtil::utcNow();
        nDXProdIdentControlPanel.AnzahlEtiketten = real2int(roundUp(sysWizard.parmOrderQty() /
        ( unitOfMeasureConversionLoc.Factor ? unitOfMeasureConversionLoc.Factor : 1), 1));
        nDXProdIdentControlPanel.TechniqueId = nDXProdIdentTechniqueLoc.ID;
        nDXProdIdentControlPanel.RefRecIdUnitConvert = unitOfMeasureConversionLoc.RecId;
        nDXProdIdentControlPanel.LabelId = nDXProdIdentLabelLoc.ID;
        nDXProdIdentControlPanel.LabelIdProdIdent = nDXProdIdentLabelLoc.ID;
        nDXProdIdentControlPanel.LabelFoundOK = true;
        nDXProdIdentControlPanel.OprIdOK = routeLoc.RecId != 0;
        nDXProdIdentControlPanel.OprNumOK = routeLoc.RecId != 0;
        nDXProdIdentControlPanel.ProdIdentExists = true;
        NDXProdIdent::fillControlPanelAddition(nDXProdIdentControlPanel, true);
        nDXProdIdentControlPanel.ProdIdentControlPanelManual = NoYes::Yes;
        nDXProdIdentControlPanel.ToSync = NoYes::Yes;
        ttsbegin;
        if (nDXProdIdentControlPanel.validateWrite())
        {
            nDXProdIdentControlPanel.write();
            sysWizard.addNDXProdIdentControlPanelList(nDXProdIdentControlPanel);
            if (lFirst)
            {
                nDXProdIdentControlPanelParentRecId = nDXProdIdentControlPanel.RecId;
                lFirst = false;
            }
        }
        ttscommit;
    }
    if (nDXProdIdentControlPanelParentRecId)
    {
        NDXProdIdentControlPanelLine::fillFromRecordList(nDXProdIdentControlPanelParentRecId, sysWizard.parmNDXProdIdentControlPanelList());
    }
}

/// <summary>
/// PaffH 11.05.24
/// </summary>
/// <param name = "_contract">Niedax.AzureServiceBus.Models.PALabel.NDXProdIdentControlPanelContract</param>
public void updateNDXProdIdentControlPanelFromContract(Niedax.AzureServiceBus.Models.PALabel.NDXProdIdentControlPanelContract _contract)
{
    if (!_contract.RecIdNDXProdIdentControlPanel)
    {
        return;
    }
    NDXProdIdentControlPanel nDXProdIdentControlPanel = NDXProdIdentControlPanel::findRecId(_contract.RecIdNDXProdIdentControlPanel, true);
    nDXProdIdentControlPanel.BT_RecordId = _contract.BT_RecordId;
    NDXProdIdentBTStatus nDXProdIdentBTStatus;
    try
    {
        nDXProdIdentControlPanel.BT_Status = _contract.BT_Status;
    }
    catch
    {
        error(strFmt("@NDXBase:NDXEnumNotFound", _contract.BT_Status));
        nDXProdIdentControlPanel.BT_Status = NDXProdIdentBTStatus::ohneZuordnung;
    }
    nDXProdIdentControlPanel.BT_StatusDateTime = _contract.BT_StatusDateTime;
    nDXProdIdentControlPanel.BT_StatusUserId = _contract.BT_StatusUserId;
    ttsbegin;
    if (nDXProdIdentControlPanel.validateWrite())
    {
        nDXProdIdentControlPanel.write();
        sysWizard.addNDXProdIdentControlPanelList(nDXProdIdentControlPanel);
    }
    ttscommit;

}

/// <summary>
/// PaffH 02.05.24
/// </summary>
public void init()
{
    super();
    if (element.args().caller())
    {
        sysWizard = element.args().caller();
    }
    else
    {
        NDXManualPALabelWizard::main(new Args());
        element.closeCancel();
    }
    InventTable locInventTable = sysWizard.parmInventTable();
    SysQuery::findOrCreateRange(InventTable_ds.queryBuildDataSource(), fieldNum(InventTable, RecId)).value(queryValue(locInventTable.RecId));
    InventTable_ds.executeQuery();


}

/// <summary>
/// PaffH 02.05.24
